define({"topics":[{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_9.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e34502","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_8.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e34606","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_7.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e34710","topics":[]},{"title":"Removing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Removes the service access vent from the magnet enclosure allowing a ladder to stand close to the magnet on the left-hand side.<\/p>","href":"t_RemovingTheServiceAccessVent_6.html","attributes":{"data-id":"id_2002970"},"menu":{"hasChildren":false},"tocID":"id_2002970-d46e34814","topics":[]},{"title":"Removing the magnet left-hand lower rear cover","shortdesc":"<p class=\"shortdesc\">Removes the lower cover from the left-hand rear corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandLowerRearCover.html","attributes":{"data-id":"id_2002991"},"menu":{"hasChildren":false},"tocID":"id_2002991-d46e34918","topics":[]}]});